<?php
declare(strict_types=1);require __DIR__.'/app/bootstrap.php';
$redirect=(string)($_GET['redirect_uri']??$_POST['redirect_uri']??'');$state=(string)($_GET['state']??$_POST['state']??'');
$parts=parse_url($redirect);$host=strtolower((string)($parts['host']??''));$valid=($parts['scheme']??'')==='https' && str_ends_with($host,'.chromiumapp.org');
if(!$valid){http_response_code(400);exit('Invalid extension redirect.');}
$u=current_user($pdo);if(!$u){$_SESSION['after_login']=$_SERVER['REQUEST_URI'];header('Location:/login.php');exit;}
if($_SERVER['REQUEST_METHOD']==='POST'){require_csrf();$raw=bin2hex(random_bytes(32));$hash=hash('sha256',$raw);$pdo->prepare('DELETE FROM extension_auth_codes WHERE expires_at<NOW() OR used_at IS NOT NULL')->execute();$q=$pdo->prepare('INSERT INTO extension_auth_codes(user_id,code_hash,redirect_uri,expires_at) VALUES(?,?,?,DATE_ADD(NOW(),INTERVAL 5 MINUTE))');$q->execute([$u['id'],$hash,$redirect]);$sep=str_contains($redirect,'?')?'&':'?';header('Location:'.$redirect.$sep.http_build_query(['code'=>$raw,'state'=>$state]));exit;}
?><!doctype html><html><head><meta charset="utf-8"><title>Connect Annotated</title><link rel="stylesheet" href="/assets/css/app.css"></head><body><main class="panel narrow"><h1>Connect Annotated extension</h1><p>Connect the Chrome sidebar to <strong><?=h($u['display_name'])?></strong> (@<?=h($u['username'])?>).</p><p>The extension will receive a revocable session token. It will not receive your password or OAuth credentials.</p><form method="post"><input type="hidden" name="csrf" value="<?=h(csrf_token())?>"><input type="hidden" name="redirect_uri" value="<?=h($redirect)?>"><input type="hidden" name="state" value="<?=h($state)?>"><button>Connect extension</button></form></main></body></html>
